"""Upgrade cached v8 groups without recreating sources or fixture settings."""
import bpy
from . import runtime, path_ray_nodes, centerline_surface_nodes


def upgrade(network):
    """Replace only outdated shared terminal/path helpers in a saved v8 graph.

    This is a build-time operation. Normal vertex editing remains native GN.
    The builders also emit the corrected helpers when starting from scratch.
    """
    runtime.solver_modules()
    builders = (
        ('Extend through redundant collinear samples', path_ray_nodes.NAME,
         path_ray_nodes.build),
        ('Every editable carriageway and separator exactly once',
         'Prochitecture Streets / Dynamic Bundle Section surfaces v1',
         lambda: centerline_surface_nodes.build(local_diagnostics=True, dynamic_bundles=True)),
    )
    for label, name, builder in builders:
        node = network.nodes[label]
        old = node.node_tree
        if old.get('smooth_join_support') == 1:
            continue
        cached = bpy.data.node_groups.get(name)
        displaced = None
        if cached and cached.get('smooth_join_support') != 1:
            displaced = cached
            displaced.name = name + ' before smooth join update'
        try:
            new = builder()
        except Exception:
            if displaced:
                partial = bpy.data.node_groups.get(name)
                if partial and partial.users == 0:
                    bpy.data.node_groups.remove(partial)
                displaced.name = name
            raise
        old.user_remap(new)
        separate_cache = displaced is not None and displaced != old
        if old.users == 0:
            bpy.data.node_groups.remove(old)
        if separate_cache:
            displaced.name = name + ' legacy cache'
    return network
